 if 'sbix' in tables:
  o,l,_=tables['sbix']; print('sbix head', data[o:o+min(l,64)].hex())
  version,flags,count=struct.unpack('>HHI',data[o:o+8]); print(version,flags,count)
  offs=struct.unpack('>'+'I'*min(count,5), data[o+8:o+8+4*min(count,5)])
